    ecology: 'The cunning cousins of common ogres — larger, smarter, and capable of magic. They rule tribes of lesser giants and ogres through a combination of brute force and sorcery. Some live among mortals in disguise, using Change Shape to pass as human. Far more dangerous than their size suggests.',
    behavior: 'Opens invisible. Cone of Cold on grouped enemies. Glaive in melee with terrifying reach. Frost Ray at range. Regeneration makes sustained fights difficult. Gaseous form to escape. Fights intelligently — retreats and returns.',
