    physicalDescription: 'Ten feet tall with blue-tinged skin and small ivory horns. In its true form, it\'s an imposing giant with frost-crusted armor. In disguise, a tall, pale human who keeps to shadows. Intelligence gleams in its eyes.',
    weakness: 'Fire and acid stop its regeneration. Dispel Magic removes its disguise. True Seeing reveals its form. In its natural shape, it\'s too large to hide. Without regeneration, it\'s surprisingly cautious.',
    loreHook: 'The new mercenary captain is winning every engagement. Too well. His soldiers are oddly loyal and terrified of him in equal measure. And the defeated enemies are never found — just frost on the battlefield.',
